for p, col, lab in ((0.5, 'mint', '0,5% → 90%'), (1, 'moon', '1% → 82%'), (2, 'amber', '2% → 67%'), (5, 'rose', '5% → 36%')):
    pts = [(X(n), Y(100 * (1 - p / 100) ** n)) for n in range(21)]
    pa.append(poly(pts, col, 3)); pa.append(dot(*pts[-1], col))
