def chips(y, label, vals, total, col):
    o = [t(30, y + 27, label, col, 18)]
    x = 120
    for v in vals:
        w = 58 + (6 if v >= 100 else 0)
        o.append(rect(x, y, w, 40, col, .14, rx=10)); o.append(t(x + w / 2, y + 27, f'${v}', col, 17, 'middle'))
        x += w + 12
    o.append(t(x + 4, y + 27, f'= ${total}', col, 18))
    return o
pb += chips(130, 'Етап 1', [1, 3, 6, 12, 24, 54], 100, 'mint')
